# Let me verify the remaining mappings
data_cols = [1, 4, 7, 10, 13]

print("=== Complete input column classification by zero set ===")
input_col_sets = {}
for c in data_cols:
    zeros = [r for r in range(13) if demos['input'][r][c] == 0]
    input_col_sets[c] = set(zeros)
    print(f"Input Col {c}: {sorted(zeros)}")

print("\n=== Complete output column classification by zero set ===")
output_col_sets = {}
for c in data_cols:
    zeros = [r for r in range(13) if demos['output'][r][c] == 0]
    output_col_sets[c] = set(zeros)
    print(f"Output Col {c}: {sorted(zeros)}")

# Match them up
print("\n=== Matching ===")
for out_c, out_z in output_col_sets.items():
    found = None
    for in_c, in_z in input_col_sets.items():
        if out_z == in_z:
            found = in_c
            break
    if found:
        print(f"Output Col {out_c} = Input Col {found}")
    else:
        print(f"Output Col {out_c}: no matching input col. {out_z} - subset of which input cols?")
        # Check if it's a subset of some input cols
        for in_c, in_z in input_col_sets.items():
            if out_z.issubset(in_z):
                print(f"  subset of Input Col {in_c}: {in_z}")

# Now I need to figure out output Col 10 and output Col 13 sources
# Maybe they come from specific INPUT rows' patterns?

# Test on all kept demo pairs
print("=== Testing on all kept demo pairs ===")

test_results = []
for test_id, test_data in demos.items():
    if test_data is None:
        continue
    if test_data['input'] is None:
        continue
    test_output = transform_simple(test_data['input'])
    test_results.append((test_id, test_output == test_data['output']))
    if test_output != test_data['output']:
        print(f"{test_id}: MISMATCH")
        for r in range(13):
            if test_output[r] != test_data['output'][r]:
                print(f"  Row {r}: got {test_output[r]}, expected {test_data['output'][r]}")
    else:
        print(f"{test_id}: PASS")

if all(v for _, v in test_results):
    print("\n=== ALL TESTS PASSED ===")

# Inspect demos structure
print(f"demos type: {type(demos)}")
if isinstance(demos, dict):
    print(f"demos keys: {list(demos.keys())}")
else:
    print(f"demos length/type: {type(demos)}")
    if isinstance(demos, list):
        print(f"First element: {demos[0] if demos else 'empty'}")

